import{z as l,x as B,o as t,c as p,q as E,j as s,D as e,d as r,s as i,S as d,b as o}from"./chunks/framework.C8m1ZpeB.js";const U=JSON.parse('{"title":"未定义行为与优化","description":"","frontmatter":{"title":"未定义行为与优化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/undefined-behavior-opt.md","filePath":"cs/undefined-behavior-opt.md","lastUpdated":1791413859000}'),A={name:"cs/undefined-behavior-opt.md"};function c(h,a,m,u,f,D){const n=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=E('<h1 id="未定义行为与优化" tabindex="-1">未定义行为与优化 <a class="header-anchor" href="#未定义行为与优化" aria-label="Permalink to &quot;未定义行为与优化&quot;">​</a></h1><div class="epigraph"><p>语言把某些状态标成未定义，优化器可假设它们不发生。于是「程序员觉得会做什么」与「生成代码做什么」在 UB 处分裂。</p><footer>—— 据 ISO C/C++ 未定义行为条款；Lattner, What Every C Programmer Should Know About Undefined Behavior；CompCert 对定义行为子集的对照整理</footer></div><p>上一课<a href="/cs/lto">LTO</a>让分析看见更多路径。缺口是<strong>合法变换的上限</strong>：有符号溢出、野指针、数据竞争（C）是 UB，优化可删检查、把循环当无限、根据「不能越界」收紧范围。本课钉「假设不发生」如何变成变换，不把全部 UB 列表当百科。中端课序在此收紧契约。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/type-soundness">健全性</a> 相对「出错状态」才有意义。C 的出错是 UB，语义允许任何目标码。优化：<code>if (p) load p; load p</code> 第二次可提前，因空指针 UB。缺口是<strong>把标准当许可</strong>，不是区间格细节。</p><p><span class="marginnote">「UB」可以理解成编译器的免检通行证：语言把某些状态（有符号溢出、解引用野指针）标成「不允许发生」，优化器于是放心假设它们不存在，顺手删掉你写的防御性检查。</span></p><p>程序员用溢出当绕回，优化可删 <code>if (x+1&lt;x)</code>。这是误解契约，不是编译器随机坏。</p><h3 id="ub-不是未指定或实现定义" tabindex="-1">UB 不是未指定或实现定义 <a class="header-anchor" href="#ub-不是未指定或实现定义" aria-label="Permalink to &quot;UB 不是未指定或实现定义&quot;">​</a></h3><p>未指定：选一种；实现定义：必须文档。UB：无要求。不要三词混用。</p><p><span class="marginnote">ISO C 3.4.3。Lattner 的系列短文。Regehr 的博客与 cse473 课常见材料。CompCert 选可定义子集。本课不发明标准条款编号之外的「秘密 UB」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>IR 带 <code>nsw</code>/<code>nuw</code>/<code>inbounds</code> 等毒标志，把源语言 UB 显式化。变换：利用毒值传播、立即 UB 则后继不可达。诊断：sanitize（ASan/UBSan）在另一配置关闭这些假设。</p>',12)),(t(),s(d,null,{default:e(()=>[i(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%E7%A8%8B%E5%BA%8F%22%5D%20--%3E%20UB%5B%22%E8%AF%AD%E8%A8%80%20UB%22%5D%0A%20%20UB%20--%3E%20ASSUME%5B%22%E4%BC%98%E5%8C%96%E5%81%87%E8%AE%BE%E4%B8%8D%E5%8F%91%E7%94%9F%22%5D%0A%20%20ASSUME%20--%3E%20XFORM%5B%22%E6%BF%80%E8%BF%9B%E5%8F%98%E6%8D%A2%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("p",null,"与值范围、LICM、别名（TBAA）都吃同一口粮。fast-math 是浮点侧的类似开关，下一课。",-1)),a[4]||(a[4]=o("h2",{id:"机制",tabindex:"-1"},[r("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=o("p",null,"poison 与立即 UB 在 IR 里走的是两条不同的触发线：",-1)),(t(),s(d,null,{default:e(()=>[i(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20NSW%5B%22%E5%B8%A6%20nsw%20%E7%9A%84%E5%8A%A0%E6%B3%95%E6%BA%A2%E5%87%BA%22%5D%20--%3E%20POISON%5B%22%E4%BA%A7%E7%94%9F%E6%AF%92%E5%80%BC%22%5D%0A%20%20POISON%20--%3E%20PROP%5B%22%E6%AF%92%E5%80%BC%E6%B2%BF%E6%95%B0%E6%8D%AE%E6%B5%81%E4%BC%A0%E6%92%AD%22%5D%0A%20%20PROP%20--%3E%20USE%5B%22%E8%A2%AB%E5%88%86%E6%94%AF%2F%E5%AD%98%E5%82%A8%E4%BD%BF%E7%94%A8%E6%97%B6%E6%89%8D%E6%88%90%20UB%22%5D%0A%20%20WILD%5B%22%E8%A7%A3%E5%BC%95%E7%94%A8%E9%87%8E%E6%8C%87%E9%92%88%22%5D%20--%3E%20IMM%5B%22%E7%AB%8B%E5%8D%B3%20UB%22%5D%0A%20%20IMM%20--%3E%20DEAD%5B%22%E6%89%80%E5%9C%A8%E5%9D%97%E5%90%8E%E7%BB%A7%E4%B8%8D%E5%8F%AF%E8%BE%BE%22%5D%0A%20%20USE%20--%3E%20OPT%5B%22%E4%BC%98%E5%8C%96%E6%8D%AE%E6%AD%A4%E5%88%A0%E6%A3%80%E6%9F%A5%E6%88%96%E9%87%8D%E6%8E%92%22%5D%0A%20%20DEAD%20--%3E%20OPT%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=E('<p>毒值 vs 立即 UB：LLVM 区分 poison 与 UB，避免「一条毒指令核掉整个函数」过激。语言律师与 IR 律师要对齐。不要在安全语言 IR 里默许 C 的 <code>nsw</code>。</p><p><span class="marginnote">数字实例：<code>if (x+1 \\lt x) …</code> 想检测有符号回绕。x+1 溢出是 UB，优化器假设「溢出不发生」，条件恒假，整个判断被直接删除；要回绕语义得改无符号类型或加 <code>-fwrapv</code>。</span></p><p>LTO 使跨函数的 UB 假设传播更远，bug 表面更离奇。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 sanitizer。后课默认：中端合法性 ⊂ 语言未定义之外的行为。下一课 fast-math：浮点契约的显式放松。</p><p>也不把 UB 当「可以生成病毒」的许可证来讲利用；本课只讲优化契约。</p><p><span class="marginnote">常见误区：把「未指定」「实现定义」「未定义」当一个意思。未指定是编译器任选一种；实现定义是必须写进文档；UB 是无任何要求——宽容度依次放开，混用这三个词会完全错估程序行为。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>UB 让优化假设某些状态不可达。</li><li>源级「绕回」直觉与 C 有符号溢出冲突。</li><li>sanitizer 与 <code>-fwrapv</code> 等改变契约。</li><li>出处：ISO C/C++；Lattner；对照 Leroy CompCert 子集。</li></ul>',9))])}const S=l(A,[["render",c]]);export{U as __pageData,S as default};
